-- ======================================================================
-- SQL SCRIPT: TẠO VÀ CẬP NHẬT TRANG BỊ COLOR = 7 LEVEL = 100
-- CHỈ SỐ COLOR = 7 LỚN HƠN COLOR = 8 LÀ 5% (MULTIPLIER = 1.05)
-- DATABASE: htth / GameHTTH
-- ======================================================================

-- 1. BỘ 11 TRANG BỊ COLOR = 7 TIÊU BIỂU (ĐẦY ĐỦ 5 PHÁI + SLOTS)
-- Bao gồm cập nhật ID 12017..12024 và thêm mới Vũ khí 3 phái còn thiếu (12025: Dao, 12026: Gậy, 12027: Súng)
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `clazz` = VALUES(`clazz`),
  `typeequip` = VALUES(`typeequip`),
  `icon` = VALUES(`icon`),
  `level` = VALUES(`level`),
  `color` = VALUES(`color`),
  `op_1` = VALUES(`op_1`),
  `op_2` = VALUES(`op_2`),
  `part` = VALUES(`part`);

-- ======================================================================
-- 2. (TÙY CHỌN) TOÀN BỘ 48 MÓN TRANG BỊ LEVEL 100 BẢN MAX COLOR = 7 (ID 12030 -> 12077)
-- Đầy đủ từng tên gốc và biến thể 1 & 2 cho cả 5 phái + Nhẫn + Dây chuyền
-- ======================================================================
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `clazz` = VALUES(`clazz`),
  `typeequip` = VALUES(`typeequip`),
  `icon` = VALUES(`icon`),
  `level` = VALUES(`level`),
  `color` = VALUES(`color`),
  `op_1` = VALUES(`op_1`),
  `op_2` = VALUES(`op_2`),
  `part` = VALUES(`part`);
